// The runner boundary is deliberately repository-relative.  This fixture is
// created in the OS temp directory, so re-home its frozen references beneath
// that explicit approved root before invoking the production runner.
const authoritativeProspectiveRunner = options => {
  if (!options.source_bundle || !String(options.source_bundle).startsWith('/')) return runAuthoritativeProspectiveRunner(options)
  const root = dirname(options.source_bundle)
  const source = JSON.parse(readFileSync(options.source_bundle, 'utf8'))
  const roles = ['reservation', 'source_receipt', 'bar', 'feature_input', 'candidate_set', 'evaluator_code', 'signal_decision']
  const relativeSource = { ...source, ledger_path: relative(root, source.ledger_path) }
  for (const role of roles) relativeSource[role] = { ...source[role], path: relative(root, source[role].path) }
  const relativePath = join(root, `${basename(options.source_bundle, '.json')}-relative.json`)
  writeFileSync(relativePath, JSON.stringify(prospectiveWithHash(relativeSource)) + '\n')
  return runAuthoritativeProspectiveRunner({ ...options, source_bundle: basename(relativePath), workflow_root: root })
}

const dir = () => mkdtempSync(join(tmpdir(), 'strategy-ops-v5-'))
const t0 = Date.parse('2025-01-01T00:00:00.000Z')
const at = hour => new Date(t0 + hour * 3_600_000).toISOString()
const millis = value => Date.parse(value)
const asOf = at(40)
const prices = asset => Array.from({ length: 32 }, (_, i) => asset === 'btc' ? 100 + i * i * 0.25 : 200 + i * i * 0.5)

function makeRows({ includeFx = false, missingHour = null } = {}) {
  const rows = []
  for (const asset of ['btc', 'eth']) for (let i = 0; i < 32; i++) if (i !== missingHour) {
    const price = prices(asset)[i]; rows.push({ asset, symbol: `${asset.toUpperCase()}USDT`, series_type: 'TRADE_MARK', event_time: at(i), availability_time: at(i), price })
    rows.push({ asset, symbol: `${asset.toUpperCase()}USDT`, series_type: 'RISK_REFERENCE', event_time: at(i), availability_time: at(i), price: asset === 'btc' ? 100 + i * 0.5 : 200 + i })
  }
  if (includeFx) for (let i = 0; i < 32; i++) rows.push({ asset: 'usdc', symbol: 'USDCUSDT', series_type: 'COLLATERAL_FX', event_time: at(i), availability_time: at(i), price: 1 })
  return rows
}

function metadata(root, kind, records, name = kind.toLowerCase()) {
  const pitRecords = records.map(record => record && typeof record === 'object' && !Array.isArray(record)
    ? { ...record, availability_time: record.availability_time || record.effective_from || record.settlement_time || at(0) }
    : record)
  return writeMetadataArtifact(join(root, `${name}.json`), { kind, records: pitRecords, coverage: kind === 'FUNDING_IDENTITY' ? { complete: true, cadence_ms: 129_600_000, anchor_time: pitRecords[0]?.settlement_time || at(0) } : null })
}
function spotMetadata(root) {
  const common = { effective_from: at(-1), effective_to: at(40) }
  return metadata(root, 'FEE_SCHEDULE', ['BTCUSDT', 'ETHUSDT'].map(symbol => ({ ...common, venue: 'binance', symbol, taker_rate: 0.001 })), 'fees')
}
function basePolicy(overrides = {}) { return { venue: 'binance', interval_ms: 3_600_000, current_equity: 10_000, max_concurrent: 2, max_reserved_fraction: 0.01, allow_fixture_metadata: true, execution_fixture: true, asOf, ...overrides } }
function baseTrades() {
  return [
    { signal_id: 'btc-1', asset: 'btc', venue: 'binance', symbol: 'BTCUSDT', instrument_type: 'spot', direction: 'long', quantity: 1, entry_time: at(0), exit_time: at(31), stop_price: 90, notional: 100 },
    { signal_id: 'eth-1', asset: 'eth', venue: 'binance', symbol: 'ETHUSDT', instrument_type: 'spot', direction: 'long', quantity: 0.5, entry_time: at(0), exit_time: at(31), stop_price: 180, notional: 100 }
  ]
}

test('portfolio risk binds physical metadata and computes 32-point PnL covariance/MRC', () => {
  const root = dir(); const marks = writeMarkArtifact(join(root, 'marks.json'), { intervalMs: 3_600_000, rows: makeRows() }); const fees = spotMetadata(root)
  const result = evaluatePortfolioRiskV5({ markPath: marks.path, markSha256: marks.sha256, metadata: { feeArtifactPath: fees.path, feeArtifactSha256: fees.sha256 }, requiredAssets: ['btc', 'eth'], policy: basePolicy(), trades: baseTrades() })
  assert.equal(result.provenance, 'FIXTURE'); assert.equal(result.pass, false); assert.equal(result.marginal_risk_contribution.status, 'MEASURED'); assert.ok(result.marginal_risk_contribution.common_timestamps >= 30); assert.ok(result.exposure.path[0].current_equity < 10_000); assert.ok(result.exposure.current_equity > 10_000); assert.ok(result.exposure.reservation_fraction < 0.01); assert.ok(result.pnl_covariance_by_asset[0][0] > 0); assert.ok(result.market_diagnostics.common_count >= 30); assert.equal(result.asset_decisions.every(row => row.status === 'FIXTURE'), true)
})

test('portfolio PnL window excludes irrelevant history and benchmark identity is never guessed', () => {
  const root = dir(); const base = writeMarkArtifact(join(root, 'base.json'), { intervalMs: 3_600_000, rows: makeRows() }); const extendedRows = makeRows(); for (const i of [-3, -2, -1, 32, 33, 34, 35]) for (const asset of ['btc', 'eth']) { const price = asset === 'btc' ? 100 + i * i * 0.25 : 200 + i * i * 0.5; extendedRows.push({ asset, symbol: `${asset.toUpperCase()}USDT`, series_type: 'TRADE_MARK', event_time: at(i), availability_time: at(i), price }); extendedRows.push({ asset, symbol: `${asset.toUpperCase()}USDT`, series_type: 'RISK_REFERENCE', event_time: at(i), availability_time: at(i), price: asset === 'btc' ? 100 + i * 0.5 : 200 + i }) } const extended = writeMarkArtifact(join(root, 'extended.json'), { intervalMs: 3_600_000, rows: extendedRows }); const fees = spotMetadata(root); const args = { metadata: { feeArtifactPath: fees.path, feeArtifactSha256: fees.sha256 }, requiredAssets: ['btc', 'eth'], policy: basePolicy(), trades: baseTrades() }; const first = evaluatePortfolioRiskV5({ ...args, markPath: base.path, markSha256: base.sha256 }); const second = evaluatePortfolioRiskV5({ ...args, markPath: extended.path, markSha256: extended.sha256 }); assert.equal(first.aligned_pnl.common_count, 32); assert.equal(second.aligned_pnl.common_count, 32); assert.deepEqual(second.pnl_covariance_by_asset, first.pnl_covariance_by_asset); assert.deepEqual(second.aligned_returns.covariance_by_asset, first.aligned_returns.covariance_by_asset); assert.deepEqual(second.aligned_returns.btc_betas, first.aligned_returns.btc_betas); assert.deepEqual(second.marginal_risk_contribution.component_sum_matches_portfolio, first.marginal_risk_contribution.component_sum_matches_portfolio)
  const ambiguousRows = [...makeRows(), ...Array.from({ length: 32 }, (_, i) => ({ asset: 'eth', symbol: 'ETHINDEX', series_type: 'RISK_REFERENCE', event_time: at(i), availability_time: at(i), price: 200 + i * 1.1 }))]; const ambiguous = writeMarkArtifact(join(root, 'ambiguous.json'), { intervalMs: 3_600_000, rows: ambiguousRows }); const blocked = evaluatePortfolioRiskV5({ ...args, markPath: ambiguous.path, markSha256: ambiguous.sha256 }); assert.ok(blocked.failures.some(row => /benchmark identity is ambiguous for eth/.test(row))); const selected = evaluatePortfolioRiskV5({ ...args, markPath: ambiguous.path, markSha256: ambiguous.sha256, policy: basePolicy({ risk_reference_symbols: { btc: 'BTCUSDT', eth: 'ETHINDEX' } }) }); assert.equal(selected.market_diagnostics.symbols.eth, 'ETHINDEX')
})

test('authoritative marks reject self-authored source-manifest provenance', () => {
  const root = dir(); const receipt = prospectiveWithHash({ schema: 'strategy-v5-source-receipt/1', version: 1, status: 'PUBLIC_OBSERVED', authoritative: true }); const receiptPath = join(root, 'receipt.json'); writeFileSync(receiptPath, JSON.stringify(receipt) + '\n'); const receiptSha = riskHash(readFileSync(receiptPath)); const codePath = join(root, 'transform.mjs'); writeFileSync(codePath, 'export const registered = true\n'); const codeSha = riskHash(readFileSync(codePath)); const lineage = riskHash({ source_manifest_sha256: receiptSha, source_receipt_sha256: receiptSha, command_receipt_sha256: receiptSha, source_code_sha256: codeSha }); assert.throws(() => writeMarkArtifact(join(root, 'attacker.json'), { provenance: 'AUTHORITATIVE_RECOMPUTED', rows: makeRows(), sourceManifestPath: receiptPath, sourceManifestSha256: receiptSha, sourceReceiptPath: receiptPath, sourceReceiptSha256: receiptSha, sourceCommandReceiptPath: receiptPath, sourceCommandReceiptSha256: receiptSha, sourceCodePath: codePath, sourceCodeSha256: codeSha, lineageSha256: lineage }), /source manifest|provenance/)
})

test('mark PIT availability is not used before completion and respects consuming cutoff', () => {
  const root = dir(); const fees = spotMetadata(root); const future = makeRows().map(row => row.series_type === 'TRADE_MARK' && row.asset === 'btc' && row.event_time === at(10) ? { ...row, availability_time: at(41) } : row); const artifact = writeMarkArtifact(join(root, 'future-mark.json'), { intervalMs: 3_600_000, rows: future }); assert.throws(() => evaluatePortfolioRiskV5({ markPath: artifact.path, markSha256: artifact.sha256, metadata: { feeArtifactPath: fees.path, feeArtifactSha256: fees.sha256 }, policy: basePolicy({ consuming_cutoff: at(40) }), trades: baseTrades() }), /as-of cutoff/); const completed = writeMarkArtifact(join(root, 'completed-mark.json'), { intervalMs: 3_600_000, rows: makeRows() }); const result = evaluatePortfolioRiskV5({ markPath: completed.path, markSha256: completed.sha256, metadata: { feeArtifactPath: fees.path, feeArtifactSha256: fees.sha256 }, policy: basePolicy({ consuming_cutoff: at(40) }), trades: baseTrades() }); assert.equal(result.provenance, 'FIXTURE')
})

test('caller fee/contract forgery and funding arithmetic mismatches fail closed', () => {
  const root = dir(); const marks = writeMarkArtifact(join(root, 'marks.json'), { intervalMs: 3_600_000, rows: makeRows() })
  const forgedFee = evaluatePortfolioRiskV5({ markPath: marks.path, markSha256: marks.sha256, policy: basePolicy(), trades: [{ ...baseTrades()[0], fee_rate: 0 }] }); assert.equal(forgedFee.accepted_trades.length, 0); assert.match(forgedFee.rejected_trades[0].reasons.join(','), /FEE_SCHEDULE|Cannot read/)
  const fees = spotMetadata(root); const wrongFees = evaluatePortfolioRiskV5({ markPath: marks.path, markSha256: marks.sha256, metadata: { feeArtifactPath: fees.path, feeArtifactSha256: fees.sha256 }, policy: basePolicy(), trades: [{ ...baseTrades()[0], fees: 0 }] }); assert.ok(wrongFees.rejected_trades[0].reasons.includes('SUPPLIED_FEES_MISMATCH_BOUND_SCHEDULE'))
  const forgedContract = evaluatePortfolioRiskV5({ markPath: marks.path, markSha256: marks.sha256, metadata: { feeArtifactPath: fees.path, feeArtifactSha256: fees.sha256 }, policy: basePolicy(), trades: [{ ...baseTrades()[0], instrument_type: 'perpetual', contract: { venue: 'binance', symbol: 'BTCUSDT', content_sha256: riskHash('self') } }] }); assert.match(forgedContract.rejected_trades[0].reasons.join(','), /CONTRACT_SPEC|BOUND_CONTRACT/)
  const source = riskHash('funding-receipt'); const contract = metadata(root, 'CONTRACT_SPEC', [{ venue: 'binance', symbol: 'BTCUSDT', effective_from: at(-1), effective_to: at(40), contract_multiplier: 1, maintenance_margin_ratio: 0.005, liquidation_price: 50, collateral_asset: 'USDT', margin_mode: 'ISOLATED', leverage: 10, expiry: at(39), settlement_time: at(38) }], 'contract'); const funding = metadata(root, 'FUNDING_IDENTITY', [{ venue: 'binance', symbol: 'BTCUSDT', event_id: 'fund-1', source_receipt_sha256: source, settlement_time: at(8), rate: 0.001 }], 'funding')
  const bad = evaluatePortfolioRiskV5({ markPath: marks.path, markSha256: marks.sha256, metadata: { feeArtifactPath: fees.path, feeArtifactSha256: fees.sha256, contractArtifactPath: contract.path, contractArtifactSha256: contract.sha256, fundingArtifactPath: funding.path, fundingArtifactSha256: funding.sha256 }, policy: basePolicy(), trades: [{ signal_id: 'perp-bad', asset: 'btc', venue: 'binance', symbol: 'BTCUSDT', instrument_type: 'perpetual', direction: 'long', quantity: 1, entry_time: at(0), exit_time: at(31), stop_price: 90, collateral_used: 100, funding_settlements: [{ event_id: 'fund-1', amount: -999, source_receipt_sha256: source }] }] }); assert.ok(bad.rejected_trades[0].reasons.some(reason => /funding amount/.test(reason)))
})

