  const root = dir(); const ledgerPath = join(root, 'ledger'); const replayPath = join(root, 'replay'); const lineage = prospectiveHash('lineage-v5'); const now = Date.now(); const receiptPath = join(root, 'receipt.json'); const completeReceipt = prospectiveWithHash({ schema: 'strategy-prospective-source-receipt/1', version: 1, source_id: 'fixture-bar-1', source: 'fixture', adapter_sha256: prospectiveHash('adapter'), code_sha256: prospectiveHash('code'), raw_byte_sha256: prospectiveHash('raw'), payload_sha256: prospectiveHash('payload'), venue: 'binance', symbol: 'BTCUSDT', timeframe: '1h', bar_start: new Date(now - 7_200_000).toISOString(), bar_end: new Date(now - 3_600_000).toISOString(), completed: true, completed_bar_id: 'bar-1', availability_time: new Date(now - 3_600_000).toISOString(), asset: 'btc', lineage_sha256: lineage }); writeFileSync(receiptPath, JSON.stringify(completeReceipt) + '\n'); const receiptHash = prospectiveHash(readFileSync(receiptPath));
