test('v5 operations schemas declare immutable contract identities', () => { for (const file of ['strategy-mark-artifact-1.schema.json', 'strategy-portfolio-risk-1.schema.json', 'strategy-portfolio-stress-result-1.schema.json', 'strategy-readiness-audit-2.schema.json', 'strategy-readiness-evidence-manifest-1.schema.json', 'strategy-prospective-ledger-2.schema.json', 'strategy-prospective-replay-registry-1.schema.json', 'strategy-prospective-publication-2.schema.json', 'strategy-prospective-trust-root-1.schema.json']) { const schema = JSON.parse(readFileSync(join(process.cwd(), 'schemas', file), 'utf8')); assert.ok(Array.isArray(schema.required) && schema.required.includes('content_sha256')) } })

test('malformed direct prospective events fail before mutating the immutable ledger', () => {
  const root = dir(); const lineage = prospectiveHash('malformed-event-lineage'); const now = Date.now(); const receiptPath = join(root, 'receipt.json'); const receipt = prospectiveWithHash({ schema: 'strategy-prospective-source-receipt/1', version: 1, source_id: 'bar', source: 'fixture', adapter_sha256: prospectiveHash('adapter'), code_sha256: prospectiveHash('code'), raw_byte_sha256: prospectiveHash('raw'), payload_sha256: prospectiveHash('payload'), venue: 'binance', symbol: 'BTCUSDT', timeframe: '1h', bar_start: new Date(now - 7_200_000).toISOString(), bar_end: new Date(now - 3_600_000).toISOString(), completed: true, completed_bar_id: 'bar-malformed', availability_time: new Date(now - 3_600_000).toISOString(), asset: 'btc', lineage_sha256: lineage }); writeFileSync(receiptPath, JSON.stringify(receipt) + '\n'); const receiptHash = prospectiveHash(readFileSync(receiptPath)); const ledger = createProspectiveLedger({ path: join(root, 'ledger'), lineageSha256: lineage, assets: ['btc'], frozenStart: now - 86_400_000, frozenEnd: now + 86_400_000 }); const before = readProspectiveLedger(join(root, 'ledger'), { nowAt: now }); assert.throws(() => appendProspectiveEvent({ path: join(root, 'ledger'), expectedHeadSha256: ledger.head_sha256, nowAt: now, event: { event_id: 'malformed', kind: 'SIGNAL', decision_time: now - 3_600_000, availability_time: now - 3_600_000, completed_bar_id: 'bar-malformed', source_receipt_path: receiptPath, source_receipt_sha256: receiptHash, lineage_sha256: lineage, asset: 'btc', payload: { signal_state: 'SHADOW', injected: true } } }), /schema|additional/i); const after = readProspectiveLedger(join(root, 'ledger'), { nowAt: now }); assert.deepEqual({ sequence: after.sequence, head: after.current_head_sha256 }, { sequence: before.sequence, head: before.current_head_sha256 })
})

test('completed-bar cycle recomputes the frozen SHADOW decision and never leaves a half-cycle', () => {
  const root = dir(); const now = Date.parse('2025-01-02T00:00:00.000Z'); const lineage = prospectiveHash('cycle-lineage'); const write = (name, value) => { const path = join(root, name); const bytes = JSON.stringify(value) + '\n'; writeFileSync(path, bytes); return { path, sha256: prospectiveHash(bytes) } }; const freeze = prospectiveWithHash({ schema: 'strategy-prospective-reservation/1', version: 1, status: 'FROZEN', decision: 'SHADOW', lineage_sha256: lineage, frozen_start: '2025-01-01T00:00:00.000Z', frozen_end: '2025-01-03T00:00:00.000Z' }); const reservation = write('cycle-reservation.json', freeze); const predictor = { id: 'edge', scalar_type: 'number', source_field: 'edge', source_family: 'CYCLE_FIXTURE', lookback_ms: 0, availability_derivation: 'completed bar close', code_sha256: prospectiveHash('predictor-code'), config_sha256: prospectiveHash('predictor-config'), pit_role: 'PREDICTOR' }; const predictors = prospectiveWithHash({ schema: 'strategy-v5-predictor-registry/1', version: 1, status: 'FROZEN', predictors: [predictor] }); const genes = prospectiveWithHash({ schema: 'strategy-v5-statistical-gene-space/1', genes: [{ name: 'threshold', type: 'continuous', min: 0, max: 4, step: 1, default: 1, usage: 'signal threshold' }] }); const spec = makeEvaluatorSpecV5({ strategyFamily: 'cycle-fixture', precommitSha256: prospectiveHash('cycle-precommit'), geneSpace: genes, predictorRegistry: predictors, predicate: { predictor_id: 'edge', op: 'GTE', value: { $gene: 'threshold' } }, candidateTemplate: { direction: 'long', entry_policy: 'NEXT_BAR_OPEN', lifecycle_timeframe: '1m', max_lifecycle_ms: 60_000, exit_policy: { type: 'TIME_STOP' } } }); const evaluator = write('cycle-evaluator.json', spec); const candidate = { candidate_id: 'cycle-candidate', definition: { threshold: 1 }, behavior_sha256: prospectiveHash('cycle-behavior'), behavior_alias_sha256: prospectiveHash('cycle-alias'), hypothesis_index: 1, generator: 'FIXTURE', behavior_vector: null, behavior_vector_sha256: null }; const candidateSet = write('cycle-candidates.json', prospectiveWithHash({ schema: 'strategy-candidate-set/5', version: 1, precommit_sha256: prospectiveHash('cycle-precommit'), experiment_sha256: prospectiveHash('cycle-experiment'), objective_contract_sha256: prospectiveHash('cycle-objective'), acceptance_sha256: prospectiveHash('cycle-acceptance'), lineage: { precommit_sha256: prospectiveHash('cycle-precommit'), experiment_sha256: prospectiveHash('cycle-experiment'), objective_contract_sha256: prospectiveHash('cycle-objective'), acceptance_sha256: prospectiveHash('cycle-acceptance') }, gene_space: genes, candidates: [candidate], declared_k: 1, effective_k: 1, aliases: [{ behavior_sha256: candidate.behavior_sha256, candidate_ids: [candidate.candidate_id] }], accounting: { fixture: true } })); const feature = write('cycle-feature-input.json', prospectiveWithHash({ schema: 'research-feature-set/1', feature_set_id: 'cycle-features', data_manifest_sha256: prospectiveHash('cycle-data'), feature_code_sha256: prospectiveHash('cycle-feature-code'), lineage: [{ dataset_id: 'cycle', source: 'fixture', pit_tier: 'COMPLETED_BAR' }], labels_allowed: false })); const bar = { asset: 'btc', completed_bar_id: 'cycle-bar-1', availability_time: '2025-01-01T01:00:00.000Z', feature_row: { edge: 2 } }; const source = write('cycle-source-receipt.json', prospectiveWithHash({ schema: 'strategy-prospective-source-receipt/1', version: 1, source_id: 'cycle-bar-1', source: 'fixture', adapter_sha256: prospectiveHash('cycle-adapter'), code_sha256: prospectiveHash('cycle-source-code'), raw_byte_sha256: prospectiveHash('cycle-raw'), payload_sha256: prospectiveHash(bar.feature_row), venue: 'binance', symbol: 'BTCUSDT', timeframe: '1h', bar_start: '2025-01-01T00:00:00.000Z', bar_end: '2025-01-01T01:00:00.000Z', completed: true, completed_bar_id: bar.completed_bar_id, asset: 'btc', availability_time: bar.availability_time, lineage_sha256: lineage })); const decisionBase = { schema: 'strategy-prospective-signal-decision/1', version: 1, decision: 'SHADOW', signal_state: 'SHADOW', signal_intent: true, candidate_id: candidate.candidate_id, completed_bar_id: bar.completed_bar_id, source_receipt_sha256: source.sha256, reservation_sha256: reservation.sha256, candidate_set_sha256: candidateSet.sha256, evaluator_code_sha256: evaluator.sha256, feature_input_sha256: feature.sha256, feature_row_sha256: prospectiveHash(bar.feature_row), availability_cutoff_time: bar.availability_time, decision_time: bar.availability_time, lineage_sha256: lineage }; const decision = write('cycle-decision.json', prospectiveWithHash(decisionBase)); const ledgerPath = join(root, 'cycle-ledger'); const ledger = createProspectiveLedger({ path: ledgerPath, lineageSha256: lineage, assets: ['btc'], frozenStart: '2025-01-01T00:00:00.000Z', frozenEnd: '2025-01-03T00:00:00.000Z' }); const args = { path: ledgerPath, reservationPath: reservation.path, reservationSha256: reservation.sha256, sourceReceiptPath: source.path, sourceReceiptSha256: source.sha256, featureInputPath: feature.path, featureInputSha256: feature.sha256, candidateSetPath: candidateSet.path, candidateSetSha256: candidateSet.sha256, evaluatorCodePath: evaluator.path, evaluatorCodeSha256: evaluator.sha256, signalDecisionPath: decision.path, signalDecisionSha256: decision.sha256, bar, expectedHeadSha256: ledger.head_sha256, nowAt: now }; const result = appendCompletedBarCycle(args); assert.equal(result.activated, false); assert.equal(readProspectiveLedger(ledgerPath, { nowAt: now }).sequence, 1); const badDecision = write('cycle-bad-decision.json', prospectiveWithHash({ ...decisionBase, signal_intent: false })); const badLedgerPath = join(root, 'bad-cycle-ledger'); const badLedger = createProspectiveLedger({ path: badLedgerPath, lineageSha256: lineage, assets: ['btc'], frozenStart: '2025-01-01T00:00:00.000Z', frozenEnd: '2025-01-03T00:00:00.000Z' }); assert.throws(() => appendCompletedBarCycle({ ...args, path: badLedgerPath, signalDecisionPath: badDecision.path, signalDecisionSha256: badDecision.sha256, expectedHeadSha256: badLedger.head_sha256 }), /byte-for-byte/); assert.equal(readProspectiveLedger(badLedgerPath, { nowAt: now }).sequence, 0); const atomicLedgerPath = join(root, 'atomic-cycle-ledger'); const atomicLedger = createProspectiveLedger({ path: atomicLedgerPath, lineageSha256: lineage, assets: ['btc'], frozenStart: '2025-01-01T00:00:00.000Z', frozenEnd: '2025-01-03T00:00:00.000Z' }); assert.throws(() => appendCompletedBarCycle({ ...args, path: atomicLedgerPath, expectedHeadSha256: atomicLedger.head_sha256, outcomeResolutionPath: join(root, 'missing-resolution.json') }), /complete physical outcome artifacts/); assert.equal(readProspectiveLedger(atomicLedgerPath, { nowAt: now }).sequence, 0); const runnerLedgerPath = join(root, 'runner-cycle-ledger'); const runnerLedger = createProspectiveLedger({ path: runnerLedgerPath, lineageSha256: lineage, assets: ['btc'], frozenStart: '2025-01-01T00:00:00.000Z', frozenEnd: '2025-01-03T00:00:00.000Z' }); const barPhysical = write('cycle-bar.json', prospectiveWithHash(bar)); const bundle = write('cycle-source-bundle.json', prospectiveWithHash({ schema: 'strategy-prospective-source-bundle/1', version: 1, status: 'FROZEN', decision: 'SHADOW', lineage_sha256: lineage, ledger_path: runnerLedgerPath, expected_head_sha256: runnerLedger.head_sha256, reservation: { path: reservation.path, byte_sha256: reservation.sha256 }, source_receipt: { path: source.path, byte_sha256: source.sha256 }, bar: { path: barPhysical.path, byte_sha256: barPhysical.sha256 }, feature_input: { path: feature.path, byte_sha256: feature.sha256 }, candidate_set: { path: candidateSet.path, byte_sha256: candidateSet.sha256 }, evaluator_code: { path: evaluator.path, byte_sha256: evaluator.sha256 }, signal_decision: { path: decision.path, byte_sha256: decision.sha256 } })); const run = authoritativeProspectiveRunner({ source_bundle: bundle.path, receipt: join(root, 'runner-receipt.json'), now_at: new Date(now).toISOString() }); assert.equal(run.status, 'COMPLETE', JSON.stringify(run.receipt)); assert.equal(readProspectiveLedger(runnerLedgerPath, { nowAt: now }).sequence, 1)
})

test('prospective append recovers every crash boundary without overwriting referenced events', () => {
  const boundaries = ['after-journal', 'after-stage-1', 'after-stage-journal-1', 'after-ready-journal', 'after-promote-1', 'after-promoted-journal', 'after-head', 'after-commit-journal']
  for (const boundary of boundaries) {
    const root = dir(); const now = Date.parse('2025-01-02T00:00:00.000Z'); const lineage = prospectiveHash(`crash-lineage-${boundary}`); const receiptPath = join(root, 'receipt.json')
    const receipt = prospectiveWithHash({ schema: 'strategy-prospective-source-receipt/1', version: 1, source_id: `crash-${boundary}`, source: 'fixture', adapter_sha256: prospectiveHash('adapter'), code_sha256: prospectiveHash('code'), raw_byte_sha256: prospectiveHash('raw'), payload_sha256: prospectiveHash('payload'), venue: 'binance', symbol: 'BTCUSDT', timeframe: '4h', bar_start: '2025-01-01T00:00:00.000Z', bar_end: '2025-01-01T04:00:00.000Z', completed: true, completed_bar_id: `bar-${boundary}`, availability_time: '2025-01-01T04:01:00.000Z', asset: 'btc', lineage_sha256: lineage })
    writeFileSync(receiptPath, JSON.stringify(receipt, null, 2) + '\n'); const receiptSha256 = prospectiveHash(readFileSync(receiptPath)); const ledgerPath = join(root, 'ledger'); const ledger = createProspectiveLedger({ path: ledgerPath, lineageSha256: lineage, assets: ['btc'], frozenStart: '2025-01-01T00:00:00.000Z', frozenEnd: '2025-01-03T00:00:00.000Z' })
    const event = { event_id: `signal-${boundary}`, kind: 'SIGNAL', decision_time: '2025-01-01T04:01:00.000Z', availability_time: '2025-01-01T04:01:00.000Z', completed_bar_id: `bar-${boundary}`, source_receipt_path: receiptPath, source_receipt_sha256: receiptSha256, lineage_sha256: lineage, asset: 'btc', payload: { signal_state: 'SHADOW' } }
    assert.throws(() => appendProspectiveEventsAtomically({ path: ledgerPath, events: [event], expectedHeadSha256: ledger.head_sha256, nowAt: now, faultHook: reached => { if (reached === boundary) throw new Error(`simulated crash at ${boundary}`) } }), /simulated crash/)
    recoverProspectiveLedger(ledgerPath)
    const recovered = readProspectiveLedger(ledgerPath, { nowAt: now }); assert.equal(recovered.sequence, 1); assert.equal(recovered.events[0].event_id, event.event_id)
    const retried = appendProspectiveEventsAtomically({ path: ledgerPath, events: [event], expectedHeadSha256: ledger.head_sha256, nowAt: now }); assert.equal(retried.length, 1); assert.equal(retried[0].event_id, event.event_id); assert.equal(readProspectiveLedger(ledgerPath, { nowAt: now }).sequence, 1)
  }
})

test('prospective runs consume the cumulative ledger head and reject stale writers', () => {
  const root = dir(); const now = Date.parse('2025-01-02T00:00:00.000Z'); const lineage = prospectiveHash('two-run-lineage'); const ledgerPath = join(root, 'ledger'); const initial = createProspectiveLedger({ path: ledgerPath, lineageSha256: lineage, assets: ['btc'], frozenStart: '2025-01-01T00:00:00.000Z', frozenEnd: '2025-01-03T00:00:00.000Z' });
  const makeReceipt = (id, hour) => { const path = join(root, `${id}-receipt.json`); const value = prospectiveWithHash({ schema: 'strategy-prospective-source-receipt/1', version: 1, source_id: id, source: 'fixture', adapter_sha256: prospectiveHash('adapter'), code_sha256: prospectiveHash('code'), raw_byte_sha256: prospectiveHash(id), payload_sha256: prospectiveHash(id), venue: 'binance', symbol: 'BTCUSDT', timeframe: '4h', bar_start: at(hour), bar_end: at(hour + 4), completed: true, completed_bar_id: id, availability_time: at(hour + 4), asset: 'btc', lineage_sha256: lineage }); writeFileSync(path, JSON.stringify(value) + '\n'); return { path, sha256: prospectiveHash(readFileSync(path)) } };
  const append = (id, hour, expectedHead) => { const receipt = makeReceipt(id, hour); return appendProspectiveEvent({ path: ledgerPath, expectedHeadSha256: expectedHead, nowAt: now, event: { event_id: `${id}:SIGNAL`, kind: 'SIGNAL', asset: 'btc', completed_bar_id: id, decision_time: at(hour + 4), availability_time: at(hour + 4), source_receipt_path: receipt.path, source_receipt_sha256: receipt.sha256, lineage_sha256: lineage, payload: { signal_state: 'SHADOW' } } }) };
  append('run-one', 0, initial.head_sha256); const afterFirst = readProspectiveLedger(ledgerPath, { nowAt: now }); assert.equal(afterFirst.sequence, 1); const firstHead = afterFirst.current_head_sha256;
  append('run-two', 8, firstHead); const afterSecond = readProspectiveLedger(ledgerPath, { nowAt: now }); assert.equal(afterSecond.sequence, 2); assert.equal(afterSecond.events[1].previous_head_sha256, firstHead);
  assert.throws(() => append('stale-run', 12, firstHead), /CAS head mismatch/); const afterStale = readProspectiveLedger(ledgerPath, { nowAt: now }); assert.equal(afterStale.sequence, 2); assert.equal(afterStale.current_head_sha256, afterSecond.current_head_sha256);
})

test('Actions attestation rejects an attacker key absent from the frozen registry', () => {
  const now = Date.parse('2025-01-02T00:00:00.000Z'); const trusted = keyPair(); const attacker = keyPair(); const registry = prospectiveWithHash({ schema: 'strategy-github-attestation-key-registry/1', version: 1, status: 'FROZEN', repository: 'owner/repo', repository_id: '1', environment: 'prospective-v5', generation: 1, keys: [{ key_id: 'actions-1', role: 'ACTIONS_ATTESTATION', public_key_pem: trusted.publicKeyPem, fingerprint: prospectiveHash(trusted.publicKeyPem), valid_from: '2025-01-01T00:00:00.000Z', valid_until: '2025-02-01T00:00:00.000Z' }] }); const registryBytesSha256 = prospectiveHash('frozen-registry-bytes'); const capture = { content_sha256: prospectiveHash('capture'), repository: 'owner/repo', repository_id: '1', oidc_subject: 'repo:owner@2/repo@1:environment:prospective-v5', oidc_signature_verified: true, evidence_branch: 'strategy-v5-evidence', evidence_branch_head_sha256: prospectiveHash('branch'), oidc_claims: { repository_id: '1', repository_owner_id: '2', environment: 'prospective-v5', workflow_ref: 'owner/repo/.github/workflows/prospective.yml@refs/heads/main', workflow_sha: 'a'.repeat(64), run_id: '42', run_attempt: 1, sub: 'repo:owner@2/repo@1:environment:prospective-v5', aud: 'strategy-v5', iss: 'https://token.actions.githubusercontent.com', iat: Math.floor(now / 1000) - 30, exp: Math.floor(now / 1000) + 600 } }; const fields = { repository: capture.repository, repository_id: capture.repository_id, workflow_sha256: capture.oidc_claims.workflow_sha, workflow_ref: capture.oidc_claims.workflow_ref, run_id: capture.oidc_claims.run_id, run_attempt: capture.oidc_claims.run_attempt, environment: capture.oidc_claims.environment, oidc_subject: capture.oidc_subject, oidc_audience: 'strategy-v5', oidc_issuer: capture.oidc_claims.iss, settings_capture_sha256: capture.content_sha256, settings_capture_byte_sha256: prospectiveHash('capture-bytes'), api_receipt_sha256: prospectiveHash('api-receipt'), cycle_receipt_sha256: prospectiveHash('cycle-receipt'), ledger_prior_head_sha256: prospectiveHash('ledger-prior'), ledger_new_head_sha256: prospectiveHash('ledger-new'), ledger_sequence: 1, trusted_key_registry_sha256: registry.content_sha256, trusted_key_registry_byte_sha256: registryBytesSha256, evidence_branch: capture.evidence_branch, evidence_branch_head_sha256: capture.evidence_branch_head_sha256, issued_at: new Date(now).toISOString(), expires_at: new Date(now + 300_000).toISOString(), nonce: 'attestation-nonce-123456' };
  const valid = signActionsAttestationV5({ fields: { ...fields, key_id: 'actions-1', public_key_pem: trusted.publicKeyPem }, privateKeyPem: trusted.privateKeyPem }); assert.equal(verifyActionsAttestation({ attestation: valid, capture, publication: null, bytesSha256: fields.settings_capture_byte_sha256, nowMs: now, pinnedFingerprint: prospectiveHash(trusted.publicKeyPem), apiReceiptSha256: fields.api_receipt_sha256, cycleReceiptSha256: fields.cycle_receipt_sha256, trustedKeyRegistry: registry, trustedKeyRegistrySha256: registry.content_sha256, trustedKeyRegistryByteSha256: registryBytesSha256 }), true)
  const forged = signActionsAttestationV5({ fields: { ...fields, key_id: 'actions-1', public_key_pem: attacker.publicKeyPem }, privateKeyPem: attacker.privateKeyPem }); assert.throws(() => verifyActionsAttestation({ attestation: forged, capture, publication: null, bytesSha256: fields.settings_capture_byte_sha256, nowMs: now, pinnedFingerprint: prospectiveHash(trusted.publicKeyPem), apiReceiptSha256: fields.api_receipt_sha256, cycleReceiptSha256: fields.cycle_receipt_sha256, trustedKeyRegistry: registry, trustedKeyRegistrySha256: registry.content_sha256, trustedKeyRegistryByteSha256: registryBytesSha256 }), /trusted registry|not in/)
})
